    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        ScannerWrapper scanner = new ScannerWrapper(inStream);
        PrintWriter writer = new PrintWriter(outStream);
        BDiv1 solver = new BDiv1();
        solver.solve(1, scanner, writer);
        writer.close();
    }

    static class BDiv1 {
        public void solve(int testNumber, ScannerWrapper in, PrintWriter out) {
            long first = in.readLong();
            long second = in.readLong();
            if (first > second) {
                long temp = first;
                first = second;
                second = temp;
            }
            if (first == 1) {
                long r = second % 6;
                switch ((int) r) {
                    case 0:
                        out.println(second);
                        break;
                    case 1:
                        out.println(second - 1);
                        break;
                    case 2:
                        out.println(second - 2);
                        break;
                    case 3:
                        out.println(second - 3);
                        break;
                    case 4:
                        out.println(second - 2);
                        break;
                    case 5:
                        out.println(second - 1);
                        break;
                }
            } else if (first == 2) {
                if (second == 2)
                    out.println(0);
                else if (second == 3)
                    out.println(4);
                else if (second == 7)
                    out.println(12);
                else
                    out.println(second * 2);
            } else {
                if ((first * second) % 2 == 1) {
                    out.println(first * second - 1);
                } else {
                    out.println(first * second);
                }
            }
        }
    }

    static class ScannerWrapper {
        private BufferedReader br;
        private StringTokenizer st;

        public ScannerWrapper(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String readLine() {
            try {
                return br.readLine();
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        public long readLong() {
            return Long.parseLong(nextToken());
        }

        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }
    }
}
